import sys,cv2,numpy as np
from scipy.interpolate import CubicSpline
sys.path.insert(0,'/workspace/submission/scripts');from matte import *;from anchors import POLYS
sys.path.insert(0,'/workspace/scratch');from localcut import cut
cv2.setNumThreads(4)
centers={0:[(226,24),(187,100)],10:[(225,23),(190,96)],20:[(238,25),(204,98)],30:[(295,25),(260,100)],40:[(387,24),(359,109)],50:[(430,22),(411,107)],60:[(374,20),(358,108)],70:[(288,20),(267,107)],80:[(245,20),(222,100)],90:[(237,19),(209,94)],99:[(234,19),(209,93)]}
# Frame-zero guide shapes are the first nearby contours displaced to the frame-zero head locations.
pol={f:[np.array(p,float) for p in pp] for f,pp in POLYS.items()}
pol[0]=[p+np.array(centers[0][o])-np.array(centers[10][o]) for o,p in enumerate(pol[10])]
# Derive adult frame-50 guide from its two surrounding poses rather than the heavily occluded view.
def resample(p,n=300):
 p=np.vstack([p,p[0]]);d=np.r_[0,np.cumsum(np.linalg.norm(np.diff(p,axis=0),axis=1))];s=np.linspace(0,d[-1],n,endpoint=False)
 return np.stack([np.interp(s,d,p[:,0]),np.interp(s,d,p[:,1])],1)
keys=sorted(pol);splines=[CubicSpline(keys,np.array([centers[k][o] for k in keys]),axis=0,bc_type='natural') for o in range(2)]
normalized={k:[resample(p)-centers[k][o] for o,p in enumerate(pp)] for k,pp in pol.items()}
normalized[50][0]=(normalized[40][0]+normalized[60][0])/2
priors=[];outs=[]
for f in range(100):
 lo=max(k for k in keys if k<=f);hi=min(k for k in keys if k>=f);t=0 if lo==hi else (f-lo)/(hi-lo)
 p=np.zeros((H,W),np.uint8)
 for o in range(2):
  points=normalized[lo][o]*(1-t)+normalized[hi][o]*t+splines[o](f)
  cv2.fillPoly(p,[np.int32(np.round(points))],1)
 priors.append(p)
 if f==0:m=initialize(2)*(1-occ(f))
 else:m=cut(read(2,f),p,occ(f))
 outs.append(m)
 if f%10==0:print('local cut',f,flush=True)
np.save(TMP/'polypriors2.npy',priors);np.save(TMP/'polycut2.npy',outs)
from PIL import Image,ImageDraw
for typ,fs in [('keys',[0,10,20,30,40,50,60,70,80,99]),('middle',[5,15,25,35,45,55,65,75,85,95])]:
 sh=Image.new('RGB',(5*512,2*312),'#555');d=ImageDraw.Draw(sh)
 for k,f in enumerate(fs):
  a=read(2,f);a[outs[f]==0]=[0,255,0];x=k%5*512;y=k//5*312;sh.paste(Image.fromarray(a[:,:,::-1]),(x,y+24));d.text((x,y),str(f))
 sh.save(TMP/f'polycut_{typ}.jpg')
PY
